from app.db import store


def get_user(user_id: int) -> dict | None:
    return store.get_by_id(user_id)


def group_counts(by: str) -> dict[str, int]:
    """Count users grouped by email domain or name initial."""
    counts: dict[str, int] = {}
    for user in store.list_users():
        if by == "domain":
            group = user["email"].rsplit("@", 1)[-1].lower()
        else:
            group = user["name"][:1].upper()
        counts[group] = counts.get(group, 0) + 1
    return counts
